00052 TCRCCalculatorLight::TCRCCalculatorLight(uint32_t bits, uint32_t truncPoly)
00053 {
00054   m_remainder = 0;
00055   m_bits = bits;
00056   m_truncPoly = truncPoly;
00057   m_finalResultMask = (1 << bits) - 1;
00058 
00059   xInitTable();
00060 }
00061 
00062 TCRCCalculatorLight::~TCRCCalculatorLight()
00063 {
00064 
00065 }
00066 
00067 void TCRCCalculatorLight::xInitTable()
00068 {
00069   const uint32_t highBit = 1 << (m_bits - 1);
00070   const uint32_t byteHighBit = 1 << (8 - 1);
00071 
00072   for (uint32_t value = 0; value < 256; value++)
00073   {
00074     uint32_t remainder = 0;
00075     for (unsigned char mask = byteHighBit; mask != 0; mask >>= 1)
00076     {
00077       if (value & mask)
00078       {
00079         remainder ^= highBit;
00080       }
00081 
00082       if (remainder & highBit)
00083       {
00084         remainder <<= 1;
00085         remainder ^= m_truncPoly;
00086       }
00087       else
00088       {
00089         remainder <<= 1;
00090       }
00091     }
00092 
00093     m_table[value] = remainder;
00094   }
00095 }
00096 
00097 void TCRCCalculatorLight::processData(unsigned char* curData, uint32_t dataLength)
00098 {
00099   for (uint32_t i = 0; i < dataLength; i++)
00100   {
00101     unsigned char index = (m_remainder >> (m_bits - 8)) ^ curData[i];
00102     m_remainder <<= 8;
00103     m_remainder ^= m_table[index];
00104   }
00105 }
