00127 void TComHash::create(int picWidth, int picHeight)
00128 {
00129   if (m_lookupTable)
00130   {
00131     clearAll();
00132   }
00133   if (!hashPic[0])
00134   {
00135     for (int k = 0; k < 5; k++)
00136     {
00137       hashPic[k] = new uint16_t[picWidth*picHeight];
00138     }
00139   }
00140   if (m_lookupTable)
00141   {
00142     return;
00143   }
00144   int maxAddr = 1 << (m_CRCBits + m_blockSizeBits);
00145   m_lookupTable = new std::vector<BlockHash>*[maxAddr];
00146   memset(m_lookupTable, 0, sizeof(std::vector<BlockHash>*) * maxAddr);
00147   tableHasContent = false;
