00240 void TComHash::generateBlock2x2HashValue(const PelUnitBuf &curPicBuf, int picWidth, int picHeight, const BitDepths bitDepths, uint32_t* picBlockHash[2], bool* picBlockSameInfo[3])
00241 {
00242   const int width = 2;
00243   const int height = 2;
00244   int xEnd = picWidth - width + 1;
00245   int yEnd = picHeight - height + 1;
00246 
00247   int length = width * 2;
00248   bool includeChroma = false;
00249   if ((curPicBuf).chromaFormat == CHROMA_444)
00250   {
00251     length *= 3;
00252     includeChroma = true;
00253   }
00254   unsigned char* p = new unsigned char[length];
00255 
00256   int pos = 0;
00257   for (int yPos = 0; yPos < yEnd; yPos++)
00258   {
00259     for (int xPos = 0; xPos < xEnd; xPos++)
00260     {
00261       TComHash::getPixelsIn1DCharArrayByBlock2x2(curPicBuf, p, xPos, yPos, bitDepths, includeChroma);
00262       picBlockSameInfo[0][pos] = isBlock2x2RowSameValue(p, includeChroma);
00263       picBlockSameInfo[1][pos] = isBlock2x2ColSameValue(p, includeChroma);
00264 
00265       picBlockHash[0][pos] = TComHash::getCRCValue1(p, length * sizeof(unsigned char));
00266       picBlockHash[1][pos] = TComHash::getCRCValue2(p, length * sizeof(unsigned char));
00267 
00268       pos++;
00269     }
00270     pos += width - 1;
00271   }
00272 
00273   delete[] p;
00274 }
00275 
00276 void TComHash::generateBlockHashValue(int picWidth, int picHeight, int width, int height, uint32_t* srcPicBlockHash[2], uint32_t* dstPicBlockHash[2], bool* srcPicBlockSameInfo[3], bool* dstPicBlockSameInfo[3])
00277 {
00278   int xEnd = picWidth - width + 1;
00279   int yEnd = picHeight - height + 1;
00280 
00281   int srcWidth = width >> 1;
00282   int quadWidth = width >> 2;
00283   int srcHeight = height >> 1;
00284   int quadHeight = height >> 2;
00285 
00286   int length = 4 * sizeof(uint32_t);
00287 
00288   uint32_t p[4];
00289   int pos = 0;
00290   for (int yPos = 0; yPos < yEnd; yPos++)
00291   {
00292     for (int xPos = 0; xPos < xEnd; xPos++)
00293     {
00294       p[0] = srcPicBlockHash[0][pos];
00295       p[1] = srcPicBlockHash[0][pos + srcWidth];
00296       p[2] = srcPicBlockHash[0][pos + srcHeight * picWidth];
00297       p[3] = srcPicBlockHash[0][pos + srcHeight * picWidth + srcWidth];
00298       dstPicBlockHash[0][pos] = TComHash::getCRCValue1((unsigned char*)p, length);
00299 
00300       p[0] = srcPicBlockHash[1][pos];
00301       p[1] = srcPicBlockHash[1][pos + srcWidth];
00302       p[2] = srcPicBlockHash[1][pos + srcHeight * picWidth];
00303       p[3] = srcPicBlockHash[1][pos + srcHeight * picWidth + srcWidth];
00304       dstPicBlockHash[1][pos] = TComHash::getCRCValue2((unsigned char*)p, length);
00305 
00306       dstPicBlockSameInfo[0][pos] = srcPicBlockSameInfo[0][pos] && srcPicBlockSameInfo[0][pos + quadWidth] && srcPicBlockSameInfo[0][pos + srcWidth]
00307         && srcPicBlockSameInfo[0][pos + srcHeight * picWidth] && srcPicBlockSameInfo[0][pos + srcHeight * picWidth + quadWidth] && srcPicBlockSameInfo[0][pos + srcHeight * picWidth + srcWidth];
00308 
00309       dstPicBlockSameInfo[1][pos] = srcPicBlockSameInfo[1][pos] && srcPicBlockSameInfo[1][pos + srcWidth] && srcPicBlockSameInfo[1][pos + quadHeight * picWidth]
00310         && srcPicBlockSameInfo[1][pos + quadHeight * picWidth + srcWidth] && srcPicBlockSameInfo[1][pos + srcHeight * picWidth] && srcPicBlockSameInfo[1][pos + srcHeight * picWidth + srcWidth];
00311 
00312       pos++;
00313     }
00314     pos += width - 1;
00315   }
00316 
00317   if (width >= 4)
00318   {
00319     pos = 0;
00320 
00321     for (int yPos = 0; yPos < yEnd; yPos++)
00322     {
00323       for (int xPos = 0; xPos < xEnd; xPos++)
00324       {
00325         dstPicBlockSameInfo[2][pos] = (!dstPicBlockSameInfo[0][pos] && !dstPicBlockSameInfo[1][pos]);
00326         pos++;
00327       }
00328       pos += width - 1;
00329     }
00330   }
00331 }
00332 
00333 void TComHash::addToHashMapByRowWithPrecalData(uint32_t* picHash[2], bool* picIsSame, int picWidth, int picHeight, int width, int height)
00334 {
00335   int xEnd = picWidth - width + 1;
00336   int yEnd = picHeight - height + 1;
00337 
00338   bool* srcIsAdded = picIsSame;
00339   uint32_t* srcHash[2] = { picHash[0], picHash[1] };
00340 
00341   int addValue = m_blockSizeToIndex[width][height];
00342   CHECK(addValue < 0, "Wrong")
00343   addValue <<= m_CRCBits;
00344   int crcMask = 1 << m_CRCBits;
00345   crcMask -= 1;
00346   int blockIdx = floorLog2(width) - 2;
00347 
00348   for (int xPos = 0; xPos < xEnd; xPos++)
00349   {
00350     for (int yPos = 0; yPos < yEnd; yPos++)
00351     {
00352       int pos = yPos * picWidth + xPos;
00353       hashPic[blockIdx][pos] = (uint16_t)(srcHash[1][pos] & crcMask);
00354       //valid data
00355       if (srcIsAdded[pos])
00356       {
00357         BlockHash blockHash;
00358         blockHash.x = xPos;
00359         blockHash.y = yPos;
00360 
00361         uint32_t hashValue1 = (srcHash[0][pos] & crcMask) + addValue;
00362         blockHash.hashValue2 = srcHash[1][pos];
00363 
00364         addToTable(hashValue1, blockHash);
00365       }
00366     }
00367   }
00368 }
