00370 void TComHash::getPixelsIn1DCharArrayByBlock2x2(const PelUnitBuf &curPicBuf, unsigned char* pixelsIn1D, int xStart, int yStart, const BitDepths& bitDepths, bool includeAllComponent)
00371 {
00372   ChromaFormat fmt = (curPicBuf).chromaFormat;
00373   if (fmt != CHROMA_444)
00374   {
00375     includeAllComponent = false;
00376   }
00377 
00378   if (bitDepths.recon[CHANNEL_TYPE_LUMA] == 8 && bitDepths.recon[CHANNEL_TYPE_CHROMA] == 8)
00379   {
00380     Pel* curPel[MAX_NUM_COMPONENT]={nullptr};
00381     int stride[MAX_NUM_COMPONENT]={0};
00382     const int maxComponent=includeAllComponent?MAX_NUM_COMPONENT:1;
00383 
00384     for (int id = 0; id < maxComponent; id++)
00385     {
00386       ComponentID compID = ComponentID(id);
00387       stride[id] = (curPicBuf).get(compID).stride;
00388       curPel[id] = (curPicBuf).get(compID).buf;
00389       curPel[id] += (yStart >> getComponentScaleY(compID, fmt)) * stride[id] + (xStart >> getComponentScaleX(compID, fmt));
00390     }
00391 
00392     int index = 0;
00393     for (int i = 0; i < 2; i++)
00394     {
00395       for (int j = 0; j < 2; j++)
00396       {
00397         pixelsIn1D[index++] = static_cast<unsigned char>(curPel[0][j]);
00398         if (includeAllComponent)
00399         {
00400           pixelsIn1D[index++] = static_cast<unsigned char>(curPel[1][j]);
00401           pixelsIn1D[index++] = static_cast<unsigned char>(curPel[2][j]);
00402         }
00403       }
00404       curPel[0] += stride[0];
00405       if (includeAllComponent)
00406       {
00407         curPel[1] += stride[1];
00408         curPel[2] += stride[2];
00409       }
00410     }
00411   }
00412   else
00413   {
00414     int shift = bitDepths.recon[CHANNEL_TYPE_LUMA] - 8;
00415     int shiftc = includeAllComponent ? (bitDepths.recon[CHANNEL_TYPE_CHROMA] - 8) : 0;
00416     Pel* curPel[MAX_NUM_COMPONENT]={nullptr};
00417     int stride[MAX_NUM_COMPONENT]={0};
00418     const int maxComponent=includeAllComponent?MAX_NUM_COMPONENT:1;
00419 
00420     for (int id = 0; id < maxComponent; id++)
00421     {
00422       ComponentID compID = ComponentID(id);
00423       stride[id] = (curPicBuf).get(compID).stride;
00424       curPel[id] = (curPicBuf).get(compID).buf;
00425       curPel[id] += (yStart >> getComponentScaleY(compID, fmt)) * stride[id] + (xStart >> getComponentScaleX(compID, fmt));
00426     }
00427 
00428     int index = 0;
00429     for (int i = 0; i < 2; i++)
00430     {
00431       for (int j = 0; j < 2; j++)
00432       {
00433         pixelsIn1D[index++] = static_cast<unsigned char>(curPel[0][j] >> shift);
00434         if (includeAllComponent)
00435         {
00436           pixelsIn1D[index++] = static_cast<unsigned char>(curPel[1][j] >> shiftc);
00437           pixelsIn1D[index++] = static_cast<unsigned char>(curPel[2][j] >> shiftc);
00438         }
00439       }
00440       curPel[0] += stride[0];
00441       if (includeAllComponent)
00442       {
00443         curPel[1] += stride[1];
00444         curPel[2] += stride[2];
00445       }
00446     }
00447   }
00448 }
