00450 bool TComHash::isBlock2x2RowSameValue(unsigned char* p, bool includeAllComponent)
00451 {
00452   if (includeAllComponent)
00453   {
00454     if (p[0] != p[3] || p[6] != p[9])
00455     {
00456       return false;
00457     }
00458     if (p[1] != p[4] || p[7] != p[10])
00459     {
00460       return false;
00461     }
00462     if (p[2] != p[5] || p[8] != p[11])
00463     {
00464       return false;
00465     }
00466   }
00467   else
00468   {
00469     if (p[0] != p[1] || p[2] != p[3])
00470     {
00471       return false;
00472     }
00473   }
00474 
00475   return true;
00476 }
00477 
00478 bool TComHash::isBlock2x2ColSameValue(unsigned char* p, bool includeAllComponent)
00479 {
00480   if (includeAllComponent)
00481   {
00482     if (p[0] != p[6] || p[3] != p[9])
00483     {
00484       return false;
00485     }
00486     if (p[1] != p[7] || p[4] != p[10])
00487     {
00488       return false;
00489     }
00490     if (p[2] != p[8] || p[5] != p[11])
00491     {
00492       return false;
00493     }
00494   }
00495   else
00496   {
00497     if ((p[0] != p[2]) || (p[1] != p[3]))
00498     {
00499       return false;
00500     }
00501   }
00502 
00503   return true;
00504 }
00505 bool TComHash::isHorizontalPerfectLuma(const Pel* srcPel, int stride, int width, int height)
00506 {
00507   for (int i = 0; i < height; i++)
00508   {
00509     for (int j = 1; j < width; j++)
00510     {
00511       if (srcPel[j] != srcPel[0])
00512       {
00513         return false;
00514       }
00515     }
00516     srcPel += stride;
00517   }
00518   return true;
00519 }
00520 
00521 bool TComHash::isVerticalPerfectLuma(const Pel* srcPel, int stride, int width, int height)
00522 {
00523   for (int i = 0; i < width; i++)
00524   {
00525     for (int j = 1; j < height; j++)
00526     {
00527       if (srcPel[j*stride + i] != srcPel[i])
00528       {
00529         return false;
00530       }
00531     }
00532   }
00533   return true;
00534 }
00535 bool TComHash::getBlockHashValue(const PelUnitBuf &curPicBuf, int width, int height, int xStart, int yStart, const BitDepths bitDepths, uint32_t& hashValue1, uint32_t& hashValue2)
00536 {
00537   int addValue = m_blockSizeToIndex[width][height];
00538 
00539   CHECK(addValue < 0, "Wrong")
00540   addValue <<= m_CRCBits;
00541   int crcMask = 1 << m_CRCBits;
00542   crcMask -= 1;
00543   int length = 4;
00544   bool includeChroma = false;
00545   if ((curPicBuf).chromaFormat == CHROMA_444)
00546   {
00547     length *= 3;
00548     includeChroma = true;
00549   }
00550 
00551   unsigned char* p = new unsigned char[length];
00552   uint32_t toHash[4];
00553 
00554   int block2x2Num = (width*height) >> 2;
00555 
00556   uint32_t* hashValueBuffer[2][2];
00557   for (int i = 0; i < 2; i++)
00558   {
00559     for (int j = 0; j < 2; j++)
00560     {
00561       hashValueBuffer[i][j] = new uint32_t[block2x2Num];
00562     }
00563   }
00564 
00565   //2x2 subblock hash values in current CU
00566   int subBlockInWidth = (width >> 1);
00567   int subBlockInHeight = (height >> 1);
00568   for (int yPos = 0; yPos < height; yPos += 2)
00569   {
00570     for (int xPos = 0; xPos < width; xPos += 2)
00571     {
00572       int pos = (yPos >> 1)*subBlockInWidth + (xPos >> 1);
00573       TComHash::getPixelsIn1DCharArrayByBlock2x2(curPicBuf, p, xStart + xPos, yStart + yPos, bitDepths, includeChroma);
00574 
00575       hashValueBuffer[0][0][pos] = TComHash::getCRCValue1(p, length * sizeof(unsigned char));
00576       hashValueBuffer[1][0][pos] = TComHash::getCRCValue2(p, length * sizeof(unsigned char));
00577     }
00578   }
00579 
00580   int srcSubBlockInWidth = subBlockInWidth;
00581   subBlockInWidth >>= 1;
00582   subBlockInHeight >>= 1;
00583   length = 4 * sizeof(uint32_t);
00584 
00585   int srcIdx = 1;
00586   int dstIdx = 0;
00587 
00588   //4x4 subblock hash values to current block hash values
00589   int minSize = std::min(height, width);
00590   for (int subWidth = 4; subWidth <= minSize; subWidth *= 2)
00591   {
00592     srcIdx = 1 - srcIdx;
00593     dstIdx = 1 - dstIdx;
00594 
00595     int dstPos = 0;
00596     for (int yPos = 0; yPos < subBlockInHeight; yPos++)
00597     {
00598       for (int xPos = 0; xPos < subBlockInWidth; xPos++)
00599       {
00600         int srcPos = (yPos << 1)*srcSubBlockInWidth + (xPos << 1);
00601 
00602         toHash[0] = hashValueBuffer[0][srcIdx][srcPos];
00603         toHash[1] = hashValueBuffer[0][srcIdx][srcPos + 1];
00604         toHash[2] = hashValueBuffer[0][srcIdx][srcPos + srcSubBlockInWidth];
00605         toHash[3] = hashValueBuffer[0][srcIdx][srcPos + srcSubBlockInWidth + 1];
00606 
00607         hashValueBuffer[0][dstIdx][dstPos] = TComHash::getCRCValue1((unsigned char*)toHash, length);
00608 
00609         toHash[0] = hashValueBuffer[1][srcIdx][srcPos];
00610         toHash[1] = hashValueBuffer[1][srcIdx][srcPos + 1];
00611         toHash[2] = hashValueBuffer[1][srcIdx][srcPos + srcSubBlockInWidth];
00612         toHash[3] = hashValueBuffer[1][srcIdx][srcPos + srcSubBlockInWidth + 1];
00613         hashValueBuffer[1][dstIdx][dstPos] = TComHash::getCRCValue2((unsigned char*)toHash, length);
00614 
00615         dstPos++;
00616       }
00617     }
00618 
00619     srcSubBlockInWidth = subBlockInWidth;
00620     subBlockInWidth >>= 1;
00621     subBlockInHeight >>= 1;
00622   }
00623 
00624   if (width != height)//currently support 1:2 or 2:1 block size
00625   {
00626     CHECK(width != (height << 1) && (width << 1) != height, "Wrong")
00627     bool isHorizontal = width == (height << 1) ? true : false;
00628     length = 2 * sizeof(uint32_t);
00629     srcIdx = 1 - srcIdx;
00630     dstIdx = 1 - dstIdx;
00631     if (isHorizontal)
00632     {
00633       toHash[0] = hashValueBuffer[0][srcIdx][0];
00634       toHash[1] = hashValueBuffer[0][srcIdx][1];
00635 
00636       hashValueBuffer[0][dstIdx][0] = TComHash::getCRCValue1((unsigned char*)toHash, length);
00637 
00638       toHash[0] = hashValueBuffer[1][srcIdx][0];
00639       toHash[1] = hashValueBuffer[1][srcIdx][1];
00640       hashValueBuffer[1][dstIdx][0] = TComHash::getCRCValue2((unsigned char*)toHash, length);
00641     }
00642     else
00643     {
00644       CHECK(srcSubBlockInWidth != 1, "Wrong")
00645       toHash[0] = hashValueBuffer[0][srcIdx][0];
00646       toHash[1] = hashValueBuffer[0][srcIdx][srcSubBlockInWidth];
00647 
00648       hashValueBuffer[0][dstIdx][0] = TComHash::getCRCValue1((unsigned char*)toHash, length);
00649 
00650       toHash[0] = hashValueBuffer[1][srcIdx][0];
00651       toHash[1] = hashValueBuffer[1][srcIdx][srcSubBlockInWidth];
00652       hashValueBuffer[1][dstIdx][0] = TComHash::getCRCValue2((unsigned char*)toHash, length);
00653     }
00654   }
00655 
00656   hashValue1 = (hashValueBuffer[0][dstIdx][0] & crcMask) + addValue;
00657   hashValue2 = hashValueBuffer[1][dstIdx][0];
00658 
00659   for (int i = 0; i < 2; i++)
00660   {
00661     for (int j = 0; j < 2; j++)
00662     {
00663       delete[] hashValueBuffer[i][j];
00664     }
00665   }
00666 
00667   delete[] p;
00668 
00669   return true;
00670 }
