00672 void TComHash::initBlockSizeToIndex()
00673 {
00674   for (int i = 0; i < 65; i++)
00675   {
00676     for (int j = 0; j < 65; j++)
00677     {
00678       m_blockSizeToIndex[i][j] = -1;
00679     }
00680   }
00681 
00682   m_blockSizeToIndex[8][8] = 0;
00683   m_blockSizeToIndex[16][16] = 1;
00684   m_blockSizeToIndex[32][32] = 2;
00685   m_blockSizeToIndex[64][64] = 3;
00686   m_blockSizeToIndex[4][4] = 4;
00687 }
